def choose_move(observation):
    w = observation['grid_width']
    h = observation['grid_height']
    px, py = observation['self_position']
    ox, oy = observation['opponent_position']
    obs_positions = observation.get('obstacles', [])
    res_positions = observation.get('resources', [])
    remaining = observation['remaining_resource_count']
    score_self = observation['scores'][0]
    score_opp = observation['scores'][1]

    def safe_move(dx, dy):
        nx, ny = px + dx, py + dy
        if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obs_positions:
            return True
        return False

    # Determine move towards resource if available
    def towards_target(tx, ty):
        dx = dy = 0
        if tx > px:
            dx = 1
        elif tx < px:
            dx = -1
        if ty > py:
            dy = 1
        elif ty < py:
            dy = -1
        if safe_move(dx, dy):
            return [dx, dy]
        # Try alternative directions
        for ddx, ddy in [(1,0), (-1,0), (0,1), (0,-1)]:
            if safe_move(ddx, ddy):
                return [ddx, ddy]
        return [0, 0]

    # Find nearest resource
    min_dist = float('inf')
    target = None
    for (rx, ry) in res_positions:
        dist = abs(rx - px) + abs(ry - py)
        if dist < min_dist:
            min_dist = dist
            target = (rx, ry)

    # Decide move
    if remaining > 0 and target:
        move = towards_target(*target)
        if move != [0, 0]:
            return move

    # If no resources left, or unreachable, move to improve score difference
    # Move towards opponent if behind or explore randomly
    if score_self <= score_opp:
        # Move towards opponent
        move = towards_target(ox, oy)
        if move != [0, 0]:
            return move

    # Else, random safe move
    for dx, dy in [(1,0), (-1,0), (0,1), (0,-1)]:
        if safe_move(dx, dy):
            return [dx, dy]

    return [0, 0]
